110	void downgrade_executor::stop()
111	{
112	  bool expected = true;
113	  if (!_running.compare_exchange_strong(expected, false)) { return; }
114	
115	  _pool->interrupt();
116	  _request_queue.interrupt();
117	  _monitor_cv.notify_one();
118	
119	  if (_monitor_thread.joinable()) { _monitor_thread.join(); }
120	  if (_processing_thread.joinable()) { _processing_thread.join(); }
121	
122	  _pool->wait_all();
123	  cancel_pending_requests();
124	  _pool->stop();
125	  _pool.reset();
126	  _stream_pool.reset();
127	}
