// ---------------------------------------------------------------------------
// Memory layout for the reschedule test:
//   Allocation    = 400 MB per task (much larger than the 50 MB reservation)
//
// With 3 threads, all 3 tasks start concurrently.
// Accounting after 3 reservations: 150 MB
// First  allocation (+350 MB overflow): total =  500 MB ≤ 1100 → OK
// Second allocation (+350 MB overflow): total =  850 MB ≤ 1100 → OK
// Third  allocation (+350 MB overflow): total = 1200 MB > 1100 → OOM!
//
// The OOM'd task gets rescheduled. After the first two complete, enough
// accounting headroom is freed for the rescheduled task to succeed.
// (Note: cucascade's cross-boundary deallocation accounting leaves some
//  residual in _total_allocated_bytes, hence the extra capacity margin.)
// ---------------------------------------------------------------------------
TEST_CASE("GPU pipeline executor reschedules tasks on OOM", "[gpu_pipeline_executor][oom]")
{
  oom_test_fixture f;
  if (!f.setup(3, "oom-test")) {
    WARN("Skipping OOM reschedule test — no GPU available.");
    return;
  }

  auto global_state = std::make_shared<oom_test_global_state>();

  const int num_tasks = 3;
  std::atomic<int> dispatched{0};

  f.executor->start();

  // Post-v1.0 push-model (commit 90dc104): gpu_pipeline_executor no longer publishes
  // task_requests. Schedule tasks directly onto the executor instead of waiting on
  // f.request_channel.get(). The request_channel is kept wired to preserve the
  // fixture API but is not used at runtime.
  std::thread request_handler([&]() {
    while (dispatched.load(std::memory_order_relaxed) < num_tasks) {
      auto local_state = std::make_unique<sirius::pipeline::gpu_pipeline_task_local_state>(
        std::make_unique<sirius::op::pipelineable_operator_data>(
          std::vector<std::shared_ptr<cucascade::data_batch>>{}));
      auto task = std::make_unique<oom_test_task>(
        static_cast<uint64_t>(dispatched.load(std::memory_order_relaxed)),
        std::move(local_state),
        global_state);
      f.executor->schedule(std::move(task));
      dispatched.fetch_add(1, std::memory_order_relaxed);
    }
  });

  //--------------------------------------------------------------------------
  // Wait for all tasks to complete (including rescheduled ones)
  //--------------------------------------------------------------------------
  auto start_time = std::chrono::steady_clock::now();
  auto timeout    = std::chrono::seconds(30);
  while (global_state->completed_count.load(std::memory_order_relaxed) < num_tasks) {
    std::this_thread::sleep_for(std::chrono::milliseconds(50));
    if (std::chrono::steady_clock::now() - start_time > timeout) {
      f.executor->stop();
      f.request_channel.close();
      request_handler.join();
      FAIL("Timed out waiting for OOM rescheduled tasks to complete. "
           << "Completed: " << global_state->completed_count.load()
           << ", OOM count: " << global_state->oom_count.load());
    }
  }

  f.executor->stop();
  f.request_channel.close();
  request_handler.join();

  //--------------------------------------------------------------------------
  // Validate results
  //--------------------------------------------------------------------------
  if (global_state->error_count.load(std::memory_order_relaxed) > 0) {
    std::lock_guard<std::mutex> lock(global_state->error_mutex);
    for (const auto& error : global_state->errors) {
      INFO(error);
    }
  }

  }

  REQUIRE(global_state->error_count.load(std::memory_order_relaxed) == 0);
  REQUIRE(global_state->completed_count.load(std::memory_order_relaxed) == num_tasks);
  // At least one task should have OOM'd and been rescheduled
  REQUIRE(global_state->oom_count.load(std::memory_order_relaxed) >= 1);

  INFO("OOM reschedule test passed: " << global_state->oom_count.load() << " task(s) rescheduled, "
                                      << num_tasks << " completed successfully");
}

// ---------------------------------------------------------------------------
// Test: tasks that can never succeed exhaust their retry budget (MAX_OOM_RETRIES=10)
// and cause the query to fail, while small tasks that fit in memory still complete.
//
// Memory layout:
//   GPU capacity  = 1100 MB
//   small_task    =    1 MB allocation  → always succeeds
//   xl_task       = 2048 MB allocation  → always OOMs (exceeds capacity)
//
// We dispatch 5 small tasks + 3 XL tasks = 8 total.
// The XL tasks will be rescheduled up to 10 times each before the executor
// reports a max-retry error on the completion handler.
// The 5 small tasks should all complete regardless.
// After the error, drain_and_wait() should empty the task queue.
// ---------------------------------------------------------------------------
TEST_CASE("GPU pipeline executor fails after max OOM retries",
          "[gpu_pipeline_executor][oom][max_retries]")
{
  oom_test_fixture f;
  if (!f.setup(3, "oom-retry")) {
    WARN("Skipping max-retry OOM test — no GPU available.");
    return;
  }

  auto global_state = std::make_shared<oom_test_global_state>();

  const int num_small = 5;
  const int num_xl    = 3;
  const int num_tasks = num_small + num_xl;
  std::atomic<int> dispatched{0};

  f.executor->start();

  // Post-v1.0 push-model (commit 90dc104): schedule tasks directly instead of
  // waiting on request_channel.get(). First num_small tasks become small_tasks,
  // the rest xl_tasks.
  std::thread request_handler([&]() {
    while (dispatched.load(std::memory_order_relaxed) < num_tasks) {
      auto id          = static_cast<uint64_t>(dispatched.load(std::memory_order_relaxed));
      auto local_state = std::make_unique<sirius::pipeline::gpu_pipeline_task_local_state>(
        std::make_unique<sirius::op::pipelineable_operator_data>(
          std::vector<std::shared_ptr<cucascade::data_batch>>{}));

      std::unique_ptr<sirius::parallel::itask> task;
      if (id < static_cast<uint64_t>(num_small)) {
        task = std::make_unique<small_task>(id, std::move(local_state), global_state);
      } else {
        task = std::make_unique<xl_task>(id, std::move(local_state), global_state);
      }
      f.executor->schedule(std::move(task));
      dispatched.fetch_add(1, std::memory_order_relaxed);
    }
  });

  //--------------------------------------------------------------------------
  // Wait for the completion handler to report an error (max retries exceeded)
  //--------------------------------------------------------------------------
  auto start_time = std::chrono::steady_clock::now();
  auto timeout    = std::chrono::seconds(60);
  while (!f.completion.has_error()) {
    std::this_thread::sleep_for(std::chrono::milliseconds(50));
    if (std::chrono::steady_clock::now() - start_time > timeout) {
      f.executor->stop();
      f.request_channel.close();
      request_handler.join();
      FAIL("Timed out waiting for max-retry OOM error. "
           << "Completed: " << global_state->completed_count.load()
           << ", OOM count: " << global_state->oom_count.load());
    }
  }

  //--------------------------------------------------------------------------
  // Drain remaining tasks and shut down
  //--------------------------------------------------------------------------
  f.executor->drain_and_wait();
  f.request_channel.close();
  request_handler.join();
  f.executor->stop();

  //--------------------------------------------------------------------------
  // Validate results
  //--------------------------------------------------------------------------
  if (global_state->error_count.load(std::memory_order_relaxed) > 0) {
    std::lock_guard<std::mutex> lock(global_state->error_mutex);
    for (const auto& error : global_state->errors) {
      INFO(error);
    }
  }

  // All small tasks should have completed successfully.
  REQUIRE(global_state->error_count.load(std::memory_order_relaxed) == 0);
  REQUIRE(global_state->completed_count.load(std::memory_order_relaxed) == num_small);

  // The completion handler should be in an error state from exceeding max retries.
  REQUIRE(f.completion.has_error());

  // XL tasks should have OOM'd many times (at least 10 for the one that hit the limit).
  REQUIRE(global_state->oom_count.load(std::memory_order_relaxed) >= 10);

  // After drain_and_wait(), the task queue should be empty.
  REQUIRE(f.executor->is_task_queue_empty());

  INFO("Max-retry OOM test passed: " << global_state->oom_count.load() << " OOM events, "
                                     << global_state->completed_count.load()
                                     << " small tasks completed, error correctly reported");
}

 * @param requested_memory_space  Target memory space; may be nullptr to use the batch's current
 *                                space.
 * @param stream                  CUDA stream used for any data-movement kernels.
 * @return A read_only_data_batch holding the shared lock (on the clone for cross-GPU inputs),
 *         or std::nullopt on failure.
 * @throws rmm::out_of_memory  If a GPU memory allocation fails during the conversion or clone.
 */
inline std::optional<cucascade::read_only_data_batch> lock_or_prepare_batch(
  const std::shared_ptr<cucascade::data_batch>& batch,
  const cucascade::memory::memory_space* requested_memory_space,
  rmm::cuda_stream_view stream)
{
  if (!batch) { return std::nullopt; }

  // Opportunistic stream rebind (best-effort, non-blocking): if the batch already resides in
  // the target GPU memory space, rebind its deallocation stream to this task's stream so that
  // when the task later frees the data the free lands on the active stream's free list rather
  // than on the stream the data was produced on. We use try_to_mutable() so we never block --
  // if another reader holds the batch (e.g. a probe task on another GPU sharing a build batch)
  // or it is otherwise busy, we simply skip the rebind; correctness is unaffected. Gating on a
  // space match guarantees the stream and the data live on the same device (important for
  // multi-GPU). The mismatch case below converts via `stream`, which already allocates the new
  // table on it, so no rebind is needed there.
  if (auto mut = batch->try_to_mutable()) {
    const auto* current_space = mut->get_memory_space();
    const auto* rebind_target =
      requested_memory_space != nullptr ? requested_memory_space : current_space;
    if (current_space != nullptr && rebind_target != nullptr &&
        current_space->get_id() == rebind_target->get_id() &&
        rebind_target->get_tier() == cucascade::memory::Tier::GPU) {
      mut->rebind_stream(stream);
    }
  }

  // Acquire a read-only lock
  auto read_accessor = batch->to_read_only();

  // Determine the target memory space
  const auto* target_space =
    requested_memory_space != nullptr ? requested_memory_space : read_accessor.get_memory_space();
  if (target_space == nullptr) { return std::nullopt; }

  // Memory space matches — return the read-only accessor directly
  if (read_accessor.get_memory_space() != nullptr &&
      read_accessor.get_memory_space()->get_id() == target_space->get_id()) {
    return std::move(read_accessor);
  }

  // Memory space mismatch — clone or move depending on where the data lives.
  auto& registry = sirius::converter_registry::get();

  switch (target_space->get_tier()) {
    case cucascade::memory::Tier::GPU: {
      if (read_accessor.get_current_tier() == cucascade::memory::Tier::GPU) {
        // Cross-GPU: clone into the target space under the shared lock. The source is never
        // exclusively locked or mutated. clone_to routes through convert_gpu_to_gpu, which waits
        // on the source's writer event and synchronizes its copy stream before returning, so
        // holding read_accessor across the call is sufficient ordering and the copy is complete
        // when it returns. No normalize_gpu_list_offsets here: that fixup only reverses the
        // INT64 offsets promotion of host->GPU reconstruction, and a GPU->GPU copy preserves the
        // source's column types (a GPU-resident source is already normalized — the same-space
        // fast path above depends on that invariant).
        auto clone = read_accessor.clone_to<cucascade::gpu_table_representation>(
          registry, sirius::get_next_batch_id(), target_space, stream);
        return clone->to_read_only();
      }
      // HOST/DISK -> GPU upgrade/readback: convert in place (move), freeing the spilled copy.
      auto mut_accessor = cucascade::data_batch::readonly_to_mutable(std::move(read_accessor));
      // readonly_to_mutable is not atomic (shared released, then exclusive acquired): a
      // concurrent consumer of a shared spilled batch may have converted it in the gap.
      // Re-dispatch on the state observed under the exclusive lock:
      const auto* current_space = mut_accessor.get_memory_space();
      if (current_space != nullptr && current_space->get_id() == target_space->get_id()) {
        // Already in the target space — skip the wasteful same-space deep copy.
        return cucascade::data_batch::mutable_to_readonly(std::move(mut_accessor));
      }
      if (mut_accessor.get_current_tier() == cucascade::memory::Tier::GPU) {
        // Upgraded to a DIFFERENT GPU in the gap: never move a GPU-resident batch cross-device
        // (that would steal it from the device that just materialized it) — clone instead. The
        // clone happens under the exclusive lock we already hold; pinning the state here avoids
        // yet another non-atomic lock transition.
        auto clone = mut_accessor.clone_to<cucascade::gpu_table_representation>(
          registry, sirius::get_next_batch_id(), target_space, stream);
        return clone->to_read_only();
      }
      mut_accessor.convert_to<cucascade::gpu_table_representation>(registry, target_space, stream);
      telemetry::batch_telemetry_registry::instance().on_tier_change(
        mut_accessor.get_batch_id(),
        target_space->get_tier(),
        target_space->get_id().device_id,
        mut_accessor.get_data()->get_size_in_bytes());
      return cucascade::data_batch::mutable_to_readonly(std::move(mut_accessor));
    }
    case cucascade::memory::Tier::HOST: {
      auto mut_accessor = cucascade::data_batch::readonly_to_mutable(std::move(read_accessor));
      // Same non-atomic-upgrade race as the GPU arm: skip if already in the target space.
      if (mut_accessor.get_memory_space() == nullptr ||
          mut_accessor.get_memory_space()->get_id() != target_space->get_id()) {
        auto host_reservation =
          const_cast<cucascade::memory::memory_space*>(target_space)
            ->make_reservation_or_null(mut_accessor.get_data()->get_size_in_bytes());
        if (host_reservation != nullptr) {
          mut_accessor.convert_to<cucascade::host_data_representation>(
            registry, *host_reservation, stream);
        } else {
          SIRIUS_LOG_WARN(
            "lock_or_prepare_batch: host reservation failed for batch {} ({} bytes) — "
            "proceeding without reservation, converter may OOM",
            mut_accessor.get_batch_id(),
            mut_accessor.get_data()->get_size_in_bytes());
          mut_accessor.convert_to<cucascade::host_data_representation>(
            registry, target_space, stream);
        }
        telemetry::batch_telemetry_registry::instance().on_tier_change(
          mut_accessor.get_batch_id(),
          target_space->get_tier(),
          target_space->get_id().device_id,
          mut_accessor.get_data()->get_size_in_bytes());
      }
      return cucascade::data_batch::mutable_to_readonly(std::move(mut_accessor));
    }
    default:
      SIRIUS_LOG_ERROR("lock_or_prepare_batch: unsupported target tier for batch {}",
                       read_accessor.get_batch_id());
      return std::nullopt;
  }
}

